import{M as e}from"./chunk-I35EDW7W.js";var o={id:"present-simple",slug:"present-simple",level:"cap1",topicTag:"tenses",titleVi:"Th\xEC hi\u1EC7n t\u1EA1i \u0111\u01A1n",titleEn:"Present Simple",explanationVi:'Th\xEC hi\u1EC7n t\u1EA1i \u0111\u01A1n d\xF9ng \u0111\u1EC3 n\xF3i v\u1EC1 nh\u1EEFng vi\u1EC7c x\u1EA3y ra th\u01B0\u1EDDng xuy\xEAn ho\u1EB7c lu\xF4n \u0111\xFAng. V\u1EDBi "I/You/We/They" ta d\xF9ng \u0111\u1ED9ng t\u1EEB nguy\xEAn th\u1EC3, v\u1EDBi "He/She/It" ta th\xEAm "s" ho\u1EB7c "es" v\xE0o sau \u0111\u1ED9ng t\u1EEB.',examples:[{en:"I like dogs.",vi:"Em th\xEDch nh\u1EEFng ch\xFA ch\xF3."},{en:"She likes cats.",vi:"C\xF4 \u1EA5y th\xEDch nh\u1EEFng ch\xFA m\xE8o."},{en:"We play every day.",vi:"Ch\xFAng em ch\u01A1i m\u1ED7i ng\xE0y."},{en:"He goes to school.",vi:"C\u1EADu \u1EA5y \u0111i h\u1ECDc."}]};var s={id:"basic-sentence-patterns",slug:"basic-sentence-patterns",level:"cap1",topicTag:"sentence-patterns",titleVi:"M\u1EABu c\xE2u c\u01A1 b\u1EA3n: I am / You are / This is",titleEn:"Basic Sentence Patterns",explanationVi:'\u0110\xE2y l\xE0 nh\u1EEFng m\u1EABu c\xE2u \u0111\u1EA7u ti\xEAn c\xE1c em c\u1EA7n nh\u1EDB: "I am" (T\xF4i l\xE0), "You are" (B\u1EA1n l\xE0), "This is" (\u0110\xE2y l\xE0). Ch\xFAng d\xF9ng \u0111\u1EC3 gi\u1EDBi thi\u1EC7u b\u1EA3n th\xE2n, ng\u01B0\u1EDDi kh\xE1c ho\u1EB7c \u0111\u1ED3 v\u1EADt.',examples:[{en:"I am Linh.",vi:"T\xF4i l\xE0 Linh."},{en:"You are my friend.",vi:"B\u1EA1n l\xE0 b\u1EA1n c\u1EE7a t\xF4i."},{en:"This is my mother.",vi:"\u0110\xE2y l\xE0 m\u1EB9 c\u1EE7a t\xF4i."},{en:"This is a cat.",vi:"\u0110\xE2y l\xE0 m\u1ED9t con m\xE8o."}]};var a={id:"question-forms",slug:"question-forms",level:"cap1",topicTag:"questions",titleVi:"C\xE2u h\u1ECFi c\u01A1 b\u1EA3n: What / Where / How",titleEn:"Basic Questions",explanationVi:'C\xE1c t\u1EEB \u0111\u1EC3 h\u1ECFi th\u01B0\u1EDDng g\u1EB7p: "What" (C\xE1i g\xEC), "Where" (\u1EDE \u0111\xE2u), "How" (Nh\u01B0 th\u1EBF n\xE0o). Ngo\xE0i ra c\xF2n c\xF3 c\xE2u h\u1ECFi Yes/No b\u1EAFt \u0111\u1EA7u b\u1EB1ng \u0111\u1ED9ng t\u1EEB "to be" ho\u1EB7c tr\u1EE3 \u0111\u1ED9ng t\u1EEB.',examples:[{en:"What is this?",vi:"\u0110\xE2y l\xE0 c\xE1i g\xEC?"},{en:"Where is the book?",vi:"Quy\u1EC3n s\xE1ch \u1EDF \u0111\xE2u?"},{en:"How are you?",vi:"B\u1EA1n kh\u1ECFe kh\xF4ng?"},{en:"Is this a dog?",vi:"\u0110\xE2y c\xF3 ph\u1EA3i l\xE0 con ch\xF3 kh\xF4ng?"}]};var h={id:"plural-nouns",slug:"plural-nouns",level:"cap2",topicTag:"nouns",titleVi:"Danh t\u1EEB s\u1ED1 nhi\u1EC1u",titleEn:"Plural Nouns",explanationVi:'\u0110\u1EC3 n\xF3i nhi\u1EC1u h\u01A1n m\u1ED9t \u0111\u1ED3 v\u1EADt ho\u1EB7c con v\u1EADt, ta th\u01B0\u1EDDng th\xEAm "s" v\xE0o cu\u1ED1i danh t\u1EEB. M\u1ED9t s\u1ED1 t\u1EEB \u0111\u1EB7c bi\u1EC7t c\xF3 d\u1EA1ng s\u1ED1 nhi\u1EC1u kh\xE1c, v\xED d\u1EE5 "child" th\xE0nh "children".',examples:[{en:"one cat, two cats",vi:"m\u1ED9t con m\xE8o, hai con m\xE8o"},{en:"one book, three books",vi:"m\u1ED9t quy\u1EC3n s\xE1ch, ba quy\u1EC3n s\xE1ch"},{en:"one child, two children",vi:"m\u1ED9t \u0111\u1EE9a tr\u1EBB, hai \u0111\u1EE9a tr\u1EBB"},{en:"one fish, many fish",vi:"m\u1ED9t con c\xE1, nhi\u1EC1u con c\xE1"}]};var r={id:"past-simple",slug:"past-simple",level:"cap3",topicTag:"tenses",titleVi:"Th\xEC qu\xE1 kh\u1EE9 \u0111\u01A1n",titleEn:"Past Simple",explanationVi:'Th\xEC qu\xE1 kh\u1EE9 \u0111\u01A1n d\xF9ng \u0111\u1EC3 n\xF3i v\u1EC1 h\xE0nh \u0111\u1ED9ng \u0111\xE3 x\u1EA3y ra v\xE0 k\u1EBFt th\xFAc trong qu\xE1 kh\u1EE9. V\u1EDBi \u0111\u1ED9ng t\u1EEB c\xF3 quy t\u1EAFc, ta th\xEAm "-ed" v\xE0o sau \u0111\u1ED9ng t\u1EEB. V\u1EDBi \u0111\u1ED9ng t\u1EEB b\u1EA5t quy t\u1EAFc, ta ph\u1EA3i h\u1ECDc thu\u1ED9c d\u1EA1ng qu\xE1 kh\u1EE9 ri\xEAng (v\xED d\u1EE5: go \u2192 went, see \u2192 saw).',examples:[{en:"I visited my grandmother last week.",vi:"Tu\u1EA7n tr\u01B0\u1EDBc t\xF4i \u0111\xE3 \u0111\u1EBFn th\u0103m b\xE0."},{en:"She watched a movie yesterday.",vi:"H\xF4m qua c\xF4 \u1EA5y \u0111\xE3 xem m\u1ED9t b\u1ED9 phim."},{en:"They went to Da Lat last summer.",vi:"M\xF9a h\xE8 n\u0103m ngo\xE1i h\u1ECD \u0111\xE3 \u0111i \u0110\xE0 L\u1EA1t."},{en:"Did you finish your homework?",vi:"B\u1EA1n \u0111\xE3 l\xE0m xong b\xE0i t\u1EADp ch\u01B0a?"}]};var m={id:"comparatives",slug:"comparatives",level:"cap3",topicTag:"comparatives",titleVi:"So s\xE1nh h\u01A1n v\xE0 so s\xE1nh nh\u1EA5t",titleEn:"Comparatives and Superlatives",explanationVi:'T\xEDnh t\u1EEB ng\u1EAFn (1 \xE2m ti\u1EBFt) th\xEAm "-er"/"-est"; t\xEDnh t\u1EEB d\xE0i (2 \xE2m ti\u1EBFt tr\u1EDF l\xEAn) d\xF9ng "more"/"most" tr\u01B0\u1EDBc t\xEDnh t\u1EEB. M\u1ED9t s\u1ED1 t\xEDnh t\u1EEB c\xF3 d\u1EA1ng \u0111\u1EB7c bi\u1EC7t: good \u2192 better \u2192 best, bad \u2192 worse \u2192 worst.',examples:[{en:"This book is more interesting than that one.",vi:"Quy\u1EC3n s\xE1ch n\xE0y th\xFA v\u1ECB h\u01A1n quy\u1EC3n kia."},{en:"She is the tallest student in the class.",vi:"C\xF4 \u1EA5y l\xE0 h\u1ECDc sinh cao nh\u1EA5t l\u1EDBp."},{en:"My English is better than before.",vi:"Ti\u1EBFng Anh c\u1EE7a t\xF4i t\u1ED1t h\u01A1n tr\u01B0\u1EDBc \u0111\xE2y."},{en:"This is the most difficult exercise in the book.",vi:"\u0110\xE2y l\xE0 b\xE0i t\u1EADp kh\xF3 nh\u1EA5t trong s\xE1ch."}]};var c={id:"passive-voice",slug:"passive-voice",level:"cap3",topicTag:"passive-voice",titleVi:"C\xE2u b\u1ECB \u0111\u1ED9ng",titleEn:"Passive Voice",explanationVi:'C\xE2u b\u1ECB \u0111\u1ED9ng d\xF9ng khi ta mu\u1ED1n nh\u1EA5n m\u1EA1nh v\xE0o \u0111\u1ED1i t\u01B0\u1EE3ng ch\u1ECBu t\xE1c \u0111\u1ED9ng c\u1EE7a h\xE0nh \u0111\u1ED9ng, thay v\xEC ng\u01B0\u1EDDi th\u1EF1c hi\u1EC7n. C\xF4ng th\u1EE9c: "to be" + Past Participle (V3/V-ed). V\xED d\u1EE5: Active "They build houses." \u2192 Passive "Houses are built (by them)."',examples:[{en:"The letter was written by Nam.",vi:"L\xE1 th\u01B0 \u0111\xE3 \u0111\u01B0\u1EE3c Nam vi\u1EBFt."},{en:"English is spoken in many countries.",vi:"Ti\u1EBFng Anh \u0111\u01B0\u1EE3c n\xF3i \u1EDF nhi\u1EC1u qu\u1ED1c gia."},{en:"This bridge was built in 1990.",vi:"C\xE2y c\u1EA7u n\xE0y \u0111\u01B0\u1EE3c x\xE2y d\u1EF1ng v\xE0o n\u0103m 1990."},{en:"The homework must be finished today.",vi:"B\xE0i t\u1EADp v\u1EC1 nh\xE0 ph\u1EA3i \u0111\u01B0\u1EE3c ho\xE0n th\xE0nh h\xF4m nay."}]};var l={id:"reported-speech",slug:"reported-speech",level:"cap3",topicTag:"reported-speech",titleVi:"C\xE2u t\u01B0\u1EDDng thu\u1EADt",titleEn:"Reported Speech",explanationVi:"C\xE2u t\u01B0\u1EDDng thu\u1EADt d\xF9ng \u0111\u1EC3 thu\u1EADt l\u1EA1i l\u1EDDi ng\u01B0\u1EDDi kh\xE1c \u0111\xE3 n\xF3i m\xE0 kh\xF4ng c\u1EA7n tr\xEDch d\u1EABn nguy\xEAn v\u0103n. Khi chuy\u1EC3n t\u1EEB c\xE2u tr\u1EF1c ti\u1EBFp sang gi\xE1n ti\u1EBFp, th\xEC c\u1EE7a \u0111\u1ED9ng t\u1EEB th\u01B0\u1EDDng l\xF9i v\u1EC1 qu\xE1 kh\u1EE9 v\xE0 \u0111\u1EA1i t\u1EEB/tr\u1EA1ng t\u1EEB ch\u1EC9 th\u1EDDi gian, n\u01A1i ch\u1ED1n c\u0169ng thay \u0111\u1ED5i cho ph\xF9 h\u1EE3p.",examples:[{en:'"I am tired," she said. \u2192 She said (that) she was tired.',vi:'"T\xF4i m\u1EC7t," c\xF4 \u1EA5y n\xF3i. \u2192 C\xF4 \u1EA5y n\xF3i r\u1EB1ng c\xF4 \u1EA5y m\u1EC7t.'},{en:'"I will call you," he said. \u2192 He said he would call me.',vi:'"T\xF4i s\u1EBD g\u1ECDi cho b\u1EA1n," anh \u1EA5y n\xF3i. \u2192 Anh \u1EA5y n\xF3i r\u1EB1ng anh \u1EA5y s\u1EBD g\u1ECDi cho t\xF4i.'},{en:'"I went there yesterday," she said. \u2192 She said she had gone there the day before.',vi:'"H\xF4m qua t\xF4i \u0111\xE3 \u0111\u1EBFn \u0111\xF3," c\xF4 \u1EA5y n\xF3i. \u2192 C\xF4 \u1EA5y n\xF3i r\u1EB1ng c\xF4 \u1EA5y \u0111\xE3 \u0111\u1EBFn \u0111\xF3 h\xF4m tr\u01B0\u1EDBc.'},{en:"He asked me where I lived.",vi:"Anh \u1EA5y h\u1ECFi t\xF4i s\u1ED1ng \u1EDF \u0111\xE2u."}]};var u={id:"conditionals",slug:"conditionals",level:"cap3",topicTag:"conditionals",titleVi:"C\xE2u \u0111i\u1EC1u ki\u1EC7n",titleEn:"Conditional Sentences",explanationVi:"C\xE2u \u0111i\u1EC1u ki\u1EC7n lo\u1EA1i 1 di\u1EC5n t\u1EA3 \u0111i\u1EC1u c\xF3 th\u1EC3 x\u1EA3y ra \u1EDF hi\u1EC7n t\u1EA1i/t\u01B0\u01A1ng lai: If + hi\u1EC7n t\u1EA1i \u0111\u01A1n, ... will + \u0111\u1ED9ng t\u1EEB nguy\xEAn th\u1EC3. C\xE2u \u0111i\u1EC1u ki\u1EC7n lo\u1EA1i 2 di\u1EC5n t\u1EA3 \u0111i\u1EC1u kh\xF4ng c\xF3 th\u1EADt \u1EDF hi\u1EC7n t\u1EA1i: If + qu\xE1 kh\u1EE9 \u0111\u01A1n, ... would + \u0111\u1ED9ng t\u1EEB nguy\xEAn th\u1EC3.",examples:[{en:"If it rains, I will stay at home.",vi:"N\u1EBFu tr\u1EDDi m\u01B0a, t\xF4i s\u1EBD \u1EDF nh\xE0."},{en:"If you study hard, you will pass the exam.",vi:"N\u1EBFu b\u1EA1n h\u1ECDc ch\u0103m ch\u1EC9, b\u1EA1n s\u1EBD v\u01B0\u1EE3t qua k\u1EF3 thi."},{en:"If I were rich, I would travel around the world.",vi:"N\u1EBFu t\xF4i gi\xE0u, t\xF4i s\u1EBD \u0111i du l\u1ECBch v\xF2ng quanh th\u1EBF gi\u1EDBi."},{en:"If I had more time, I would learn another language.",vi:"N\u1EBFu t\xF4i c\xF3 nhi\u1EC1u th\u1EDDi gian h\u01A1n, t\xF4i s\u1EBD h\u1ECDc th\xEAm m\u1ED9t ng\xF4n ng\u1EEF kh\xE1c."}]};var p=[s,o,a,h,r,m,c,l,u];var g=class n{lessons=p;getLesson(i){return this.lessons.find(t=>t.id===i)}static \u0275fac=function(t){return new(t||n)};static \u0275prov=e({token:n,factory:n.\u0275fac,providedIn:"root"})};export{g as a};
